import json
OUT=ROOT/'outputs/pysb-invoice-migration-20261013'
def fields(reader,model,wanted):
 schema=reader.call(model,'fields_get',[],{'attributes':['type','relation','string','selection']});return schema,[x for x in wanted if x in schema]
def main():
 m=Migration();a=m.a;b=m.b;OUT.mkdir(exist_ok=True)
 so=a.read('sale.order',sorted(m.maps['sale.order']),['name','invoice_ids','order_line','partner_id']);po=a.read('purchase.order',sorted(m.maps['purchase.order']),['name','invoice_ids','order_line','partner_id']);ids=sorted({i for x in so+po for i in x['invoice_ids']})
 wanted=['name','move_type','state','company_id','partner_id','commercial_partner_id','currency_id','journal_id','date','invoice_date','invoice_date_due','invoice_payment_term_id','invoice_origin','ref','payment_reference','narration','invoice_line_ids','line_ids','amount_untaxed','amount_tax','amount_total','amount_total_signed','amount_residual','payment_state','reversed_entry_id','fiscal_position_id','invoice_user_id','partner_shipping_id','invoice_partner_bank_id','write_date']
 wanted += ['invoice_currency_rate']
 sa,fa=fields(a,'account.move',wanted);sb,fb=fields(b,'account.move',wanted);source=a.read('account.move',ids,fa);target=b.search_read('account.move',[['company_id','=',1],['move_type','in',['out_invoice','in_invoice','out_refund','in_refund']]],fb+[k for k in sb if k.startswith('x_') and ('v14' in k or 'reference' in k)])
 linewanted=['name','move_id','sequence','display_type','product_id','product_uom_id','quantity','price_unit','discount','tax_ids','account_id','partner_id','currency_id','price_subtotal','price_total','balance','debit','credit','amount_currency','date_maturity','sale_line_ids','purchase_line_id','analytic_account_id','analytic_tag_ids','analytic_distribution','tax_line_id','tax_repartition_line_id']
 sla,fla=fields(a,'account.move.line',linewanted);slb,flb=fields(b,'account.move.line',linewanted);source_lines=a.read('account.move.line',sorted({i for x in source for i in x['line_ids']}),fla);target_lines=b.read('account.move.line',sorted({i for x in target for i in x['line_ids']}),flb)
 masters={}
 for model,ids,fs in [('account.account',sorted({rid(x['account_id']) for x in source_lines if x['account_id']}),['code','name','company_id','company_ids','account_type','user_type_id','reconcile','deprecated']),('account.journal',sorted({rid(x['journal_id']) for x in source}),['code','name','type','company_id','currency_id']),('account.tax',sorted({i for x in source_lines for i in x.get('tax_ids',[])}),['name','amount','amount_type','type_tax_use','price_include','include_base_amount','company_id','children_tax_ids']),('account.payment.term',sorted({rid(x['invoice_payment_term_id']) for x in source if x['invoice_payment_term_id']}),['name','line_ids']),('res.currency',sorted({rid(x['currency_id']) for x in source}),['name','rounding']),('res.partner',sorted({rid(x['partner_id']) for x in source if x['partner_id']}),['name','ref','vat','company_id'])]:
  _,f=fields(a,model,fs);_,g=fields(b,model,fs);domain=[['company_id','=',1]] if model in ['account.journal','account.tax'] else []
  masters[model]={'source':a.read(model,ids,f),'target':b.search_read(model,domain,g)}
 ex=b.search_read('ir.model.data',[['model','in',['account.move','account.move.line','res.partner','product.product','account.account','account.journal','account.tax','account.payment.term','res.currency']],['module','ilike','v14']],['module','name','model','res_id'])
 sourceids=set(m.maps['sale.order.line']);poids=set(m.maps['purchase.order.line']);mixed=[x for x in source_lines if x['id'] in {i for s in source for i in s['invoice_line_ids']} and ((x.get('sale_line_ids') and not set(x['sale_line_ids'])<=sourceids) or (x.get('purchase_line_id') and rid(x['purchase_line_id']) not in poids))]
 data={'source_database':a.db,'target_database':b.db,'company_id':1,'extracted_utc':datetime.now(timezone.utc).isoformat(),'scope':'Invoice/Bill and refunds directly linked to migrated July SO/PO; no invoice-date filter; no payments/reconciliation','so':so,'po':po,'source_moves':source,'source_lines':source_lines,'target_moves_before':target,'target_lines_before':target_lines,'schemas':{'source_move':sa,'target_move':sb,'source_line':sla,'target_line':slb},'masters':masters,'external_ids':ex,'mixed_order_lines':mixed};save(OUT/'invoice-preflight-snapshot.json',data)
 print(json.dumps({'connection':{'source':a.db,'target':b.db,'company_id':1},'so':len(so),'po':len(po),'source_documents':len(source),'source_types_states':dict(Counter(x['move_type']+'/'+x['state'] for x in source)),'source_dates':{'earliest':min((x['invoice_date'] or x['date']) for x in source),'latest':max((x['invoice_date'] or x['date']) for x in source)},'target_invoice_documents':len(target),'mixed_order_lines':len(mixed),'source_custom_line_fields':{k:v['string'] for k,v in sla.items() if k.startswith('x_') or any(t in k for t in ['discount','base_price','gift','packing'])}},ensure_ascii=False))
